// Rejects anything not signed by Convex with the shared secret, or older than 5 minutes.
const crypto = require('crypto');
const secret = $env.LENDLOOP_HMAC_SECRET;
const item = $input.first();
const headers = item.json.headers || {};
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);
const ts = String(headers['x-lendloop-timestamp'] || '');
const sig = String(headers['x-lendloop-signature'] || '');
const fresh = /^\d+$/.test(ts) && Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex');
const valid = Boolean(secret) && fresh && sig.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
return [{ json: { valid, event: valid ? JSON.parse(raw) : null } }];

// Mock channel: the message is logged here and written back to Convex, where it shows on the loan.
// Swap this node for Email/Slack/Discord; it only ever sees the recipient's id and display name.
const e = $input.first().json.event;
const who = e.recipient && e.recipient.name ? e.recipient.name : 'there';
const dates = e.startDate === e.endDate ? e.startDate : `${e.startDate} to ${e.endDate}`;
const text = {
  requested: `Hi ${who}, someone asked to borrow your ${e.tool} (${dates}).`,
  approved: `Hi ${who}, your request for the ${e.tool} (${dates}) was approved.`,
  declined: `Hi ${who}, your request for the ${e.tool} was declined.`,
  cancelled: `Hi ${who}, a request for your ${e.tool} was cancelled.`,
  returned: `Hi ${who}, the ${e.tool} was marked as returned. Thanks for borrowing!`,
}[e.status] || `Update on ${e.tool}: ${e.status}`;
console.log(`[mock notification] to user ${e.recipient && e.recipient.userId}: ${text}`);
return [{ json: { loanId: e.loanId, key: `notify:${e.eventId}`, message: text } }];

const crypto = require('crypto');
const j = $input.first().json;
const body = JSON.stringify({ key: j.key, loanId: j.loanId, kind: 'notification', status: 'sent', message: j.message });
const ts = Math.floor(Date.now() / 1000).toString();
const sig = 'sha256=' + crypto.createHmac('sha256', $env.LENDLOOP_HMAC_SECRET).update(`${ts}.${body}`).digest('hex');
return [{ json: { body, ts, sig } }];
